leNumber,    String? gender,    String? organisationType,    String? organisationName,    int? zoneId,    int? divisionId,    List<int>? regionIdList,    List<int>? trainIdList,    int? roleId,    String? employeeId,    String? panCardNo,    String? companyId,    String? aadharNo,    OrganizationItem? selectedOrganization,    ZoneItem? selectedZone,    DivisionItem? selectedDivision,    RegionItem? selectedRegion,    RoleItem? selectedRole,  }) {    return RegisterRequest(      firstName: firstName ?? this.firstName,      lastName: lastName ?? this.lastName,      email: email ?? this.email,      password: password ?? this.password,      mobileNumber: mobileNumber ?? this.mobileNumber,      gender: gender ?? this.gender,      organisationType: organisationType ?? this.organisationType,      organisationName: organisationName ?? this.organisationName,      zoneId: zoneId ?? this.zoneId,      divisionId: divisionId ?? this.divisionId,      regionIdList: regionIdList ?? this.regionIdList,      trainIdList: trainIdList ?? this.trainIdList,      roleId: roleId ?? this.roleId,      employeeId: employeeId ?? this.employeeId,      panCardNo: panCardNo ?? this.panCardNo,      companyId: companyId ?? this.companyId,      aadharNo: aadharNo ?? this.aadharNo,    );  }  Map<String, dynamic> toJsonForApi() {    return {      'first_name': firstName,      'last_name': lastName,      'email': email,      'password': password,      'mobile_number': mobileNumber,      'gender': gender,      'organisation_type': organisationType,      'organisation_name': organisationName,      'zone_id': zoneId,      'division_id': divisionId,      'region_id': regionIdList ?? [],      'train_ids': trainIdList ?? [],      'role_id': roleId,      'employee_id': employeeId,      'pan_card_no': panCardNo,      'company_id': companyId,      'aadhar_no': aadharNo,    };  }  bool isOrganisationTypeIsContractor() {    return organisationType != null &&        organisationType == OrganizationType.contractor.name;  }  factory RegisterRequest.fromJson(Map<String, dynamic> json) =>      _$RegisterRequestFromJson(json);  Map<String, dynamic> toJson() => _$RegisterRequestToJson(this);}